//! Account-bound chat history (migration 020).
//!
//! Chat history used to live only in the browser's localStorage, so it was bound
//! to one device: sign in elsewhere and the rail was empty. Every turn has in fact
//! been recorded server-side since F014 (`query_log`) — these three routes are
//! what finally let the officer who wrote a turn read it back.
//!
//! **Scoping invariant.** Every read here is filtered by `user_id` taken from the
//! session, never from the request body, and conversation ids are generated by the
//! client — so a guessed id must not open someone else's chat. This mirrors
//! `query_log::latest_since` (F022) and the `visible_source_ids` rule the citation
//! and global-search reads follow.

use axum::{extract::State, Json};
use serde::Deserialize;

use super::auth::AuthUser;
use super::{ApiError, ApiResult, AppState};
use crate::db::repositories::query_log::{self, ConversationRow, TurnRow};

/// Cap on the history rail. The rail is a navigation aid, not an archive — the
/// full record stays available through the per-user admin export.
const MAX_CONVERSATIONS: i64 = 200;

/// POST /api/list_conversations — this user's chats, most recently active first.
pub async fn list_conversations(
    State(st): State<AppState>,
    user: AuthUser,
) -> ApiResult<Json<Vec<ConversationRow>>> {
    let rows = query_log::list_conversations(&st.pool, &user.id, MAX_CONVERSATIONS)
        .await
        .map_err(|e| ApiError::internal(e.to_string()))?;
    Ok(Json(rows))
}

#[derive(Deserialize)]
pub struct ConversationReq {
    #[serde(alias = "conversationId")]
    pub conversation_id: String,
}

/// POST /api/conversation_turns — full transcript of one chat, oldest first.
///
/// An unknown or someone else's id yields an empty list rather than a 404: the
/// two are indistinguishable to the caller by design, so a probe cannot use the
/// status code to discover which conversation ids exist.
pub async fn conversation_turns(
    State(st): State<AppState>,
    user: AuthUser,
    Json(req): Json<ConversationReq>,
) -> ApiResult<Json<Vec<TurnRow>>> {
    let rows = query_log::conversation_turns(&st.pool, &user.id, &req.conversation_id)
        .await
        .map_err(|e| ApiError::internal(e.to_string()))?;
    Ok(Json(rows))
}

#[derive(serde::Serialize)]
pub struct HideResp {
    /// Turns hidden. Zero means the chat was already hidden, never existed, or
    /// belongs to another user — all of which are a successful no-op here.
    pub hidden: u64,
}

/// POST /api/hide_conversation — remove one chat from this user's history on
/// every device.
///
/// A soft delete. `query_log` is the only record of what was asked and backs the
/// admin usage panel, activity list and per-user export; a hard delete would let
/// any user punch holes in that trail. The row stays, flagged `hidden_at`, and
/// every officer-facing read skips it.
pub async fn hide_conversation(
    State(st): State<AppState>,
    user: AuthUser,
    Json(req): Json<ConversationReq>,
) -> ApiResult<Json<HideResp>> {
    let hidden = query_log::hide_conversation(&st.pool, &user.id, &req.conversation_id)
        .await
        .map_err(|e| ApiError::internal(e.to_string()))?;
    Ok(Json(HideResp { hidden }))
}
